package com.bank.statement.repository;

import com.bank.statement.model.Transaction;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;

public interface TransactionRepository extends JpaRepository<Transaction, String> {

    List<Transaction> findByAccountIdAndTxnDateBetweenOrderByTxnDateDesc(
        String accountId, LocalDate from, LocalDate to);

    @Query("SELECT SUM(CASE WHEN t.type = 'CREDIT' THEN t.amount ELSE 0 END) FROM Transaction t " +
           "WHERE t.accountId = :accountId AND t.txnDate BETWEEN :from AND :to")
    BigDecimal sumCredits(String accountId, LocalDate from, LocalDate to);

    @Query("SELECT SUM(CASE WHEN t.type = 'DEBIT' THEN t.amount ELSE 0 END) FROM Transaction t " +
           "WHERE t.accountId = :accountId AND t.txnDate BETWEEN :from AND :to")
    BigDecimal sumDebits(String accountId, LocalDate from, LocalDate to);
}
