@Slf4j
public class AutoConfigDebugRunner implements CommandLineRunner {

    private final ApplicationContext ctx;

    @Override
    public void run(String... args) {
        // These beans were AUTO-CONFIGURED — nobody defined them:
        log.info("=== Auto-configured beans ===");
        log.info("DataSource: {}", ctx.getBean(DataSource.class).getClass().getSimpleName());
        log.info("Total beans in context: {}", ctx.getBeanDefinitionCount());
        log.info("To see WHY each auto-config matched: run with --debug");
        log.info("Or check: GET /actuator/conditions");
    }
}
