package com.bank.statement.service;

import com.bank.statement.dto.*;
import com.bank.statement.model.Transaction;
import com.bank.statement.repository.TransactionRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.*;
import org.mockito.junit.jupiter.MockitoExtension;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class StatementServiceTest {

    @Mock TransactionRepository txnRepo;
    @InjectMocks StatementService statementService;

    @Test
    void shouldCalculateTotalsCorrectly() {
        LocalDate from = LocalDate.of(2024, 1, 1);
        LocalDate to = LocalDate.of(2024, 1, 31);

        when(txnRepo.findByAccountIdAndTxnDateBetweenOrderByTxnDateDesc("SAV2001", from, to))
            .thenReturn(List.of()); // simplified
        when(txnRepo.sumCredits("SAV2001", from, to)).thenReturn(new BigDecimal("300000"));
        when(txnRepo.sumDebits("SAV2001", from, to)).thenReturn(new BigDecimal("150000"));

        StatementResponse response = statementService.generateStatement(
            new StatementRequest("SAV2001", from, to));

        assertThat(response.totalCredits()).isEqualByComparingTo("300000");
        assertThat(response.totalDebits()).isEqualByComparingTo("150000");
        assertThat(response.netChange()).isEqualByComparingTo("150000");
    }
}
